    def getName(self):
        return "本地影仓 {}".format(self.VERSION)

    def _reserve_background_operation(self, operation):
        value = str(operation or "").strip()
        with self._background_operation_lock:
            active = self._background_operation
            if active:
                return False, active
            self._background_operation = value
            return True, ""

    def _release_background_operation(self, operation):
        value = str(operation or "").strip()
        with self._background_operation_lock:
            if self._background_operation == value:
                self._background_operation = ""

    def _active_background_operation(self):
        with self._background_operation_lock:
            return self._background_operation

    def _background_operation_conflict(self, active):
        labels = {
            "site_test": "后台检测",
            "package": "本地包下载安装",
            "repository": "在线仓库同步",
            "playback_proxy": "反代线路更新",
        }
        return "{}进行中，请等待当前任务完成".format(
            labels.get(str(active or ""), "后台任务")
        )

    def _ensure_background_task_active(self, cancel_event, label):
        if cancel_event.is_set() or (
            self._destroyed and not self._background_completion_allowed.is_set()
        ):
            raise BackgroundTaskCancelled("{}已取消".format(label))

    def _authorize_release(self, action):
        action = str(action or "").strip()
        if action not in ("package_download", "site_health"):
            raise ReleaseAuthorizationError("授权动作无效")
        authorization_url = str(self.AUTHORIZATION_URL or "").strip()
        authorization_key = str(self.AUTHORIZATION_KEY or "").strip()
        build_id = str(self.AUTHORIZATION_BUILD_ID or "").strip()
        # 明文可以加载本地扫描与管理，但不得执行任何远程下载或测活动作。
        # 正式发行构建必须注入三个字段，才能获得动作票据。
        if not authorization_url and not authorization_key and not build_id:
            raise ReleaseAuthorizationError(
                "当前为未发行明文版本，在线仓库、本地包下载和站点测活仅允许已发行构建"
            )
        if not authorization_url or not authorization_key or not build_id:
            raise ReleaseAuthorizationError("当前发布文件授权信息不完整")
        payload = json.dumps(
            {
                "authorization_key": authorization_key,
                "build_id": build_id,
                "action": action,
                "device_id": self.package_device_id,
            },
            ensure_ascii=False,
            separators=(",", ":"),
        ).encode("utf-8")
        request = urllib.request.Request(
            authorization_url,
            data=payload,
            headers={
                "User-Agent": "okhttp/4.12.0",
                "Accept": "application/json",
                "Content-Type": "application/json; charset=utf-8",
                "Connection": "close",
            },
            method="POST",
        )
        opener = urllib.request.build_opener(urllib.request.ProxyHandler({}))
        raw = b""
        try:
            with opener.open(
                request, timeout=max(3, int(self.AUTHORIZATION_TIMEOUT))
            ) as response:
                status = int(getattr(response, "status", response.getcode()))
                raw = response.read(64 * 1024)
        except urllib.error.HTTPError as exc:
            status = int(exc.code or 0)
            try:
                raw = exc.read(64 * 1024)
            except Exception:
                raw = b""
        except urllib.error.URLError as exc:
            raise ReleaseAuthorizationError(
                "授权服务器连接失败：{}".format(exc.reason)
            )
        except (socket.timeout, TimeoutError):
            raise ReleaseAuthorizationError("授权服务器连接超时")
        try:
            data = json.loads(raw.decode("utf-8-sig"))
        except Exception:
            raise ReleaseAuthorizationError(
                "授权服务器返回无效数据（HTTP {}）".format(status)
            )
        if not isinstance(data, dict):
            raise ReleaseAuthorizationError("授权服务器返回格式无效")
        reason = str(data.get("reason", data.get("error", "")) or "").strip()
        if status < 200 or status >= 300 or data.get("allowed") is not True:
            raise ReleaseAuthorizationError(
                reason or "当前版本未获得服务器授权"
            )
        if str(data.get("version", "")).strip() != self.VERSION:
            raise ReleaseAuthorizationError("授权版本与当前脚本不一致")
        if str(data.get("build_id", "")).strip() != build_id:
            raise ReleaseAuthorizationError("授权构建与当前脚本不一致")
        if str(data.get("action", "")).strip() != action:
            raise ReleaseAuthorizationError("授权动作与当前请求不一致")
        ticket = str(data.get("ticket", "") or "").strip()
        if not ticket:
            raise ReleaseAuthorizationError("授权服务器未返回动作票据")
        self._authorization_last_error = ""
        return ticket

    def _detect_app_mode(self):
        """探测当前进程自己的本机端口，避免多 App 同开时误判。"""
        try:
            from java import jclass

            proxy_class = jclass("com.github.catvod.Proxy")
            port = int(proxy_class.getPort())
            if port > 0:
                try:
                    payload = self._request_json(
                        "http://127.0.0.1:{}/manage/configs".format(port), 0.8
                    )
                    if isinstance(payload.get("items"), list):
                        return self.APP_MODE_WEBHTV
                except Exception:
                    pass
            try:
                jclass("com.fongmi.android.tv.setting.CustomCspSetting")
                return self.APP_MODE_WEBHTV
            except Exception:
                pass
            try:
                jclass("com.fongmi.android.tv.bean.Config")
                return self.APP_MODE_OKTV
            except Exception:
                return self.APP_MODE_UNKNOWN
        except Exception:
            # 桌面验证环境没有 Chaquopy Java bridge，保留可测试状态。
            return self.APP_MODE_UNKNOWN

    def _app_mode_label(self):
        return {
            self.APP_MODE_WEBHTV: "WebHTV",
            self.APP_MODE_OKTV: "OK影视",
        }.get(self.app_mode, "未识别环境")

    def init(self, extend=""):
        with self.lock:
            if self.inited:
                return
            external_options = self._parse_extend(extend)
            self.package_external_configured = self._has_package_download_url(
                external_options
            )
            self._apply_extend(external_options)
            self._load_roots_config()
            self.configured_scan_roots = [dict(item) for item in self.scan_roots]
            self._load_settings()
            # 外部仓库参数在本地设置读取后再次合并，确保 location.json/ext
            # 可以新增或更新同备注仓库，同时保留用户另外添加的本地仓库。
            self._apply_online_repository_options(external_options, merge=True)
            external_service_url = self._package_service_url_option(
                external_options
            )
            if external_service_url:
                self.package_service_url = external_service_url
                for item in self.package_download_sites:
                    if str(item.get("source_type", "")).lower() == "builtin":
                        item["url"] = external_service_url
                self._sync_legacy_package_download_fields()
            external_scan_base = self._scan_base_path_option(external_options)
            if external_scan_base:
                self._apply_scan_base_path(external_scan_base)
            self._migrate_builtin_package_install_directory()
            try:
                self._normalize_backup_storage()
            except Exception as exc:
                self._warn("历史备份整理失败: {}".format(exc))
            startup_warnings = list(self.status["warnings"])
            self._set_manual_idle_status()
            try:
                restored = self._restore_scan_snapshot()
            except Exception as exc:
                restored = False
                # 记入 startup_warnings，避免被补扫的状态重置覆盖
                warning = "扫描快照恢复失败: {}".format(exc)
                startup_warnings.append(warning)
                self._log("WARN", warning)
            if not restored:
                try:
                    self._auto_scan_on_enter_locked()
                except Exception as exc:
                    self._warn("进入自动补扫失败: {}".format(exc))
            if startup_warnings:
                self.status["warnings"] = list(dict.fromkeys(
                    startup_warnings + self.status["warnings"]
                ))
            self.inited = True

