    def _normalize_scan_base_path(self, value):
        path = str(value or "").strip().strip('"').strip("'")
        if path.lower().startswith("file://"):
            path = path[7:]
        if not path:
            return ""
        path = os.path.expanduser(path)
        if not os.path.isabs(path):
            path = os.path.join(self.STORAGE_ROOT, path.lstrip("/"))
        return os.path.realpath(os.path.abspath(path))

    def _scan_roots_for_base(self, base_path):
        return [
            {
                "path": _detect_child_dir(base_path, "py", "python"),
                "type": "PY",
                "extensions": [".py"],
            },
            {
                "path": _detect_child_dir(base_path, "js", "javascript"),
                "type": "JS",
                "extensions": [".js", ".json"],
            },
            {
                "path": _detect_child_dir(base_path, "csp"),
                "type": "CSP",
                "extensions": [".json"],
            },
            {
                "path": _detect_child_dir(base_path, "XBPQ"),
                "type": "XBPQ",
                "extensions": [".json"],
            },
            {
                "path": _detect_child_dir(base_path, "html"),
                "type": "HTML",
                "extensions": [".html"],
            },
        ]

    def _auto_classify_extension_map(self):
        """根据当前扫描根构建 扩展名 -> 目标子目录 的映射。
        只有映射到唯一类型的扩展名才可安全归类；.json 同时属于 JS/CSP/XBPQ，视为歧义不移动。"""
        ext_to_dirs = {}
        for root in self.scan_roots:
            directory = root.get("path")
            if not directory:
                continue
            for ext in root.get("extensions", []):
                ext_to_dirs.setdefault(ext.lower(), []).append(directory)
        unique = {}
        ambiguous = set()
        for ext, dirs in ext_to_dirs.items():
            distinct = list(dict.fromkeys(dirs))
            if len(distinct) == 1:
                unique[ext] = distinct[0]
            else:
                ambiguous.add(ext)
        return unique, ambiguous

    def _auto_classify_files(self):
        """把扫描根目录顶层散落的源文件移动到对应类型子目录。
        - 仅处理根目录顶层的普通文件，不递归、不动子目录内已归类文件。
        - 跳过符号链接、隐藏文件、管理脚本自身。
        - 目标已存在同名文件时跳过，绝不覆盖。
        - .json 等歧义扩展名不移动，计入“需手动归类”。
        返回 (moved, skipped_conflict, skipped_ambiguous, skipped_other, created_dirs, errors, detail_lines)。
        """
        base = self.local_base_dir
        if not base or not os.path.isdir(base):
            raise ValueError("扫描根目录不存在: {}".format(base or "(未设置)"))

        unique_map, ambiguous_exts = self._auto_classify_extension_map()

        moved = 0
        skipped_conflict = 0
        skipped_ambiguous = 0
        skipped_other = 0
        created_dirs = []
        errors = []
        detail = []

        try:
            entries = sorted(os.listdir(base), key=lambda v: v.lower())
        except Exception as exc:
            raise ValueError("读取扫描根目录失败: {} ({})".format(base, exc))

        self_real = None
        try:
            self_real = os.path.realpath(__file__)
        except Exception:
            self_real = None

        for name in entries:
            if name.startswith("."):
                continue
            src = os.path.join(base, name)
            try:
                if os.path.islink(src) or not os.path.isfile(src):
                    continue
            except Exception:
                continue
            src_real = os.path.realpath(src)
            if self_real and src_real == self_real:
                continue
            lower_name = name.lower()
            matched_exts = [
                ext
                for ext in set(unique_map) | ambiguous_exts
                if lower_name.endswith(ext)
            ]
            if not matched_exts:
                skipped_other += 1
                continue
            # 先匹配 .csp.json 这类多后缀，避免被末尾 .json
            # 误判为歧义文件。
            ext = max(matched_exts, key=len)
            if ext in ambiguous_exts:
                skipped_ambiguous += 1
                detail.append("歧义跳过 {}（{} 可属多个类型，请手动归类）".format(name, ext))
                continue
            target_dir = unique_map.get(ext)
            if not target_dir:
                skipped_other += 1
                continue
            destination = os.path.join(target_dir, name)
            if os.path.exists(destination):
                skipped_conflict += 1
                detail.append("冲突跳过 {}（目标已存在同名文件）".format(name))
                continue
            try:
                if not os.path.isdir(target_dir):
                    os.makedirs(target_dir, exist_ok=True)
                    created_dirs.append(target_dir)
                shutil.move(src, destination)
                moved += 1
                detail.append("已归类 {} -> {}/".format(name, os.path.basename(target_dir)))
            except Exception as exc:
                errors.append("{}: {}".format(name, exc))
                self._log("ERROR", "自动分类移动失败 {} -> {}: {}".format(src, destination, exc))

        return (
            moved,
            skipped_conflict,
            skipped_ambiguous,
            skipped_other,
            created_dirs,
            errors,
            detail,
        )

    def _run_auto_classify(self):
        """执行自动分类并生成用户可见的摘要与详情文本。调用方需持有 self.lock。
        仅移动文件，不触发扫描或重载；完成后提示用户点击“一键扫描并加载”。"""
        try:
            (
                moved,
                skipped_conflict,
                skipped_ambiguous,
                skipped_other,
                created_dirs,
                errors,
                detail,
            ) = self._auto_classify_files()
        except Exception as exc:
            self._log("ERROR", "自动分类失败: {}".format(exc))
            message = "自动分类失败：{}".format(exc)
            return message, message

        parts = ["已归类 {} 个".format(moved)]
        if skipped_conflict:
            parts.append("同名冲突跳过 {}".format(skipped_conflict))
        if skipped_ambiguous:
            parts.append("歧义(.json 等)跳过 {}".format(skipped_ambiguous))
        if skipped_other:
            parts.append("其它跳过 {}".format(skipped_other))
        if errors:
            parts.append("失败 {}".format(len(errors)))
        summary = "；".join(parts)
        if moved:
            summary += "；请点击“扫描并加载”生效"

        content_lines = [
            "扫描根目录：{}".format(self.local_base_dir),
            "本次归类：{} 个文件".format(moved),
            "同名冲突跳过：{}".format(skipped_conflict),
            "歧义扩展名跳过：{}（.json 同属 JS/CSP/XBPQ，需手动放入对应子目录）".format(
                skipped_ambiguous
            ),
            "其它跳过：{}（无扩展名或未配置类型）".format(skipped_other),
        ]
        if created_dirs:
            content_lines.append(
                "新建子目录：{}".format(
                    ", ".join(os.path.basename(d) for d in created_dirs)
                )
            )
        if detail:
            content_lines.append("")
            content_lines.append("明细:")
            content_lines.extend("- " + line for line in detail[:100])
            if len(detail) > 100:
                content_lines.append("- ...（其余 {} 条省略）".format(len(detail) - 100))
        if errors:
            content_lines.append("")
            content_lines.append("失败明细:")
            content_lines.extend("- " + line for line in errors[:50])
        content_lines.append("")
        content_lines.append(
            "仅移动文件，未触发扫描；确认无误后点击“扫描并加载”重新收录。"
        )
        self._log(
            "INFO",
            "自动分类完成: 移动 {}, 冲突 {}, 歧义 {}, 其它 {}, 失败 {}".format(
                moved, skipped_conflict, skipped_ambiguous, skipped_other, len(errors)
            ),
        )
        return summary, "\n".join(content_lines)

    def _apply_scan_base_path(self, value):
        path = self._normalize_scan_base_path(value)
        if path:
            self.scan_base_path = path
            self.local_base_dir = path
            self.scan_roots = self._scan_roots_for_base(path)
        else:
            self.scan_base_path = ""
            self.local_base_dir = self.LOCAL_BASE_DIR
            self.scan_roots = [dict(item) for item in self.configured_scan_roots]

    def _create_scan_base_tree(self, path):
        created = []
        try:
            if os.path.exists(path) and not os.path.isdir(path):
                raise ValueError("输入路径不是目录: {}".format(path))
            if not os.path.isdir(path):
                missing = []
                current = path
                while current and not os.path.exists(current):
                    missing.append(current)
                    parent = os.path.dirname(current)
                    if parent == current:
                        break
                    current = parent
                for directory in reversed(missing):
                    if os.path.isdir(directory):
                        continue
                    try:
                        os.mkdir(directory)
                    except FileExistsError:
                        if not os.path.isdir(directory):
                            raise
                    else:
                        created.append(directory)
            for root in self._scan_roots_for_base(path):
                directory = root["path"]
                if os.path.isdir(directory):
                    continue
                try:
                    os.mkdir(directory)
                except FileExistsError:
                    if not os.path.isdir(directory):
                        raise
                else:
                    created.append(directory)
            return created
        except Exception:
            self._remove_created_scan_dirs(created)
            raise

    def _remove_created_scan_dirs(self, directories):
        for directory in reversed(directories):
            try:
                os.rmdir(directory)
            except Exception:
                pass

    @staticmethod
    def _parse_health_setting_input(value, fallback, minimum, maximum, label):
        text = str(value or "").strip()
        if not text:
            return int(fallback)
        try:
            parsed = int(text, 10)
        except Exception:
            raise ValueError("{}必须是整数".format(label))
        if parsed < minimum or parsed > maximum:
            raise ValueError(
                "{}必须在 {}-{} 之间".format(label, minimum, maximum)
            )
        return parsed

    def _set_scan_and_health_settings(
        self, scan_value, concurrency_value, batch_limit_value
    ):
        path = self._normalize_scan_base_path(scan_value)
        concurrency = self._parse_health_setting_input(
            concurrency_value,
            self.SITE_TEST_CONCURRENCY,
            self.SITE_TEST_CONCURRENCY_MIN,
            self.SITE_TEST_CONCURRENCY_MAX,
            "测活线程数",
        )
        batch_limit = self._parse_health_setting_input(
            batch_limit_value,
            self.SITE_TEST_BATCH_LIMIT,
            self.SITE_TEST_BATCH_LIMIT_MIN,
            self.SITE_TEST_BATCH_LIMIT_MAX,
            "单批测活上限",
        )
        previous_path = self.scan_base_path
        previous_base = self.local_base_dir
        previous_roots = [dict(item) for item in self.scan_roots]
        previous_concurrency = self.site_test_concurrency
        previous_batch_limit = self.site_test_batch_limit
        created_dirs = []
        try:
            if path:
                created_dirs = self._create_scan_base_tree(path)
                if not os.access(path, os.R_OK):
                    raise ValueError("目录不可读: {}".format(path))
            self._apply_scan_base_path(path)
            self.site_test_concurrency = concurrency
            self.site_test_batch_limit = batch_limit
            self._save_settings()
            self._set_manual_idle_status(
                "扫描与测活参数已更新，请点击“扫描并加载”"
            )
            self._clear_scan_cache_file()
            if created_dirs:
                self._log(
                    "INFO",
                    "扫描分类目录已自动创建: {}".format(
                        ", ".join(created_dirs)
                    ),
                )
        except Exception:
            self.scan_base_path = previous_path
            self.local_base_dir = previous_base
            self.scan_roots = previous_roots
            self.site_test_concurrency = previous_concurrency
            self.site_test_batch_limit = previous_batch_limit
            self._remove_created_scan_dirs(created_dirs)
            raise
        return {
            "scan_base_path": self.scan_base_path,
            "site_test_concurrency": self.site_test_concurrency,
            "site_test_batch_limit": self.site_test_batch_limit,
        }

    def _set_scan_base_path(self, value):
        saved = self._set_scan_and_health_settings(
            value,
            str(self.site_test_concurrency),
            str(self.site_test_batch_limit),
        )
        return saved["scan_base_path"]

    def _set_pending_type_settings(self, values, block_adult_sites=None):
        previous = dict(self.pending_type_enabled)
        previous_block_adult = self.pending_block_adult_sites
        previous_dirty = self.config_dirty
        for source_type in self.TYPE_ORDER:
            if source_type in values:
                self.pending_type_enabled[source_type] = bool(values[source_type])
        if block_adult_sites is not None:
            self.pending_block_adult_sites = bool(block_adult_sites)
        self.config_dirty = any(
            self.pending_type_enabled[item] != self.type_enabled[item]
            for item in self.TYPE_ORDER
        ) or self.pending_block_adult_sites != self.block_adult_sites
        try:
            self._save_settings()
        except Exception:
            self.pending_type_enabled = previous
            self.pending_block_adult_sites = previous_block_adult
            self.config_dirty = previous_dirty
            raise
        return self.config_dirty

    def _current_android_activity(self, jclass):
        app_class = jclass("com.fongmi.android.tv.App")
        activity_class = jclass("android.app.Activity")
        modifier_class = jclass("java.lang.reflect.Modifier")
        app_info = app_class.getClass()
        activity_info = activity_class.getClass()

        for method in app_info.getDeclaredMethods():
            try:
                if not modifier_class.isStatic(method.getModifiers()):
                    continue
                if len(method.getParameterTypes()) != 0:
                    continue
                if not activity_info.isAssignableFrom(method.getReturnType()):
                    continue
                method.setAccessible(True)
                try:
                    activity = method.invoke(None, [])
                except Exception:
                    activity = method.invoke(None)
                if activity is not None:
                    return activity
            except Exception:
                continue

        app = None
        for field in app_info.getDeclaredFields():
            try:
                if not modifier_class.isStatic(field.getModifiers()):
                    continue
                if not app_info.isAssignableFrom(field.getType()):
                    continue
                field.setAccessible(True)
                app = field.get(None)
                if app is not None:
                    break
            except Exception:
                continue
        if app is not None:
            for field in app.getClass().getDeclaredFields():
                try:
                    if modifier_class.isStatic(field.getModifiers()):
                        continue
                    if not activity_info.isAssignableFrom(field.getType()):
                        continue
                    field.setAccessible(True)
                    activity = field.get(app)
                    if activity is not None:
                        return activity
                except Exception:
                    continue
        raise ValueError("未找到当前 Android 页面")

    def _android_ui_context(self, jclass):
        try:
            activity = self._current_android_activity(jclass)
            if activity is not None:
                return activity, activity
        except Exception:
            pass

        context_candidates = []
        try:
            app_class = jclass("com.fongmi.android.tv.App")
            for method_name in ("get", "getInstance", "instance"):
                try:
                    method = getattr(app_class, method_name)
                    context = method() if callable(method) else method
                    if context is not None:
                        context_candidates.append(context)
                except Exception:
                    continue
        except Exception:
            pass
        try:
            activity_thread = jclass("android.app.ActivityThread")
            context = activity_thread.currentApplication()
            if context is not None:
                context_candidates.append(context)
        except Exception:
            pass
        try:
            platform = jclass("com.chaquo.python.Python").getPlatform()
            for method_name in (
                "getApplication", "getApplicationContext", "getContext",
            ):
                try:
                    method = getattr(platform, method_name)
                    context = method() if callable(method) else method
                    if context is not None:
                        context_candidates.append(context)
                except Exception:
                    continue
        except Exception:
            pass
        return None, next(
            (context for context in context_candidates if context is not None),
            None,
        )

    def _open_scan_base_dialog(self):
        try:
            from java import dynamic_proxy, jclass

            toast_class = jclass("android.widget.Toast")
            edit_text_class = jclass("android.widget.EditText")
            linear_layout_class = jclass("android.widget.LinearLayout")
            text_view_class = jclass("android.widget.TextView")
            input_type = jclass("android.text.InputType")
            click_listener = jclass(
                "android.content.DialogInterface$OnClickListener"
            )
            view_click_listener = jclass("android.view.View$OnClickListener")
            runnable_class = jclass("java.lang.Runnable")
            try:
                builder_class = jclass(
                    "com.google.android.material.dialog.MaterialAlertDialogBuilder"
                )
            except Exception:
                builder_class = jclass("android.app.AlertDialog$Builder")
            activity = self._current_android_activity(jclass)
            owner = self

            class NoopListener(dynamic_proxy(click_listener)):
                def onClick(self, dialog, which):
                    return None

            class SaveButtonListener(dynamic_proxy(view_click_listener)):
                def __init__(self, path_edit, concurrency_edit, batch_edit, dialog):
                    super().__init__()
                    self.path_edit = path_edit
                    self.concurrency_edit = concurrency_edit
                    self.batch_edit = batch_edit
                    self.dialog = dialog

                def onClick(self, view):
                    try:
                        with owner.lock:
                            saved = owner._set_scan_and_health_settings(
                                str(self.path_edit.getText().toString()),
                                str(self.concurrency_edit.getText().toString()),
                                str(self.batch_edit.getText().toString()),
                            )
                        toast_class.makeText(
                            activity,
                            "扫描与测活参数已保存：{} 线程，单批 {}".format(
                                saved["site_test_concurrency"],
                                saved["site_test_batch_limit"],
                            ),
                            toast_class.LENGTH_LONG,
                        ).show()
                        self.dialog.dismiss()
                    except Exception as exc:
                        toast_class.makeText(
                            activity,
                            "参数保存失败: {}".format(exc),
                            toast_class.LENGTH_LONG,
                        ).show()

            class ShowDialog(dynamic_proxy(runnable_class)):
                def run(self):
                    try:
                        self._run_dialog()
                    except Exception as exc:
                        message = "扫描与测活参数输入框打开失败: {}".format(exc)
                        owner._log("ERROR", message)
                        try:
                            toast_class.makeText(
                                activity, message, toast_class.LENGTH_LONG
                            ).show()
                        except Exception:
                            owner._notify_app(message)

                def _run_dialog(self):
                    density = float(
                        activity.getResources().getDisplayMetrics().density
                    )
                    padding = int(16 * density + 0.5)
                    spacing = int(8 * density + 0.5)
                    container = linear_layout_class(activity)
                    container.setOrientation(linear_layout_class.VERTICAL)
                    container.setPadding(padding, spacing, padding, 0)

                    path_label = text_view_class(activity)
                    path_label.setText("扫描地址")
                    path_edit = edit_text_class(activity)
                    current = owner.scan_base_path
                    path_edit.setSingleLine(True)
                    path_edit.setInputType(
                        input_type.TYPE_CLASS_TEXT
                        | input_type.TYPE_TEXT_VARIATION_URI
                    )
                    path_edit.setHint(
                        "留空自动探测：{}".format(owner.local_base_dir)
                    )
                    path_edit.setText(current)
                    path_edit.setSelection(len(current))

                    concurrency_label = text_view_class(activity)
                    concurrency_label.setText("测活线程数（1-32）")
                    concurrency_label.setPadding(0, spacing, 0, 0)
                    concurrency_edit = edit_text_class(activity)
                    concurrency_edit.setSingleLine(True)
                    concurrency_edit.setInputType(
                        input_type.TYPE_CLASS_NUMBER
                        | input_type.TYPE_NUMBER_FLAG_SIGNED
                    )
                    concurrency_edit.setHint("留空使用默认 10")
                    concurrency_edit.setText(str(owner.site_test_concurrency))

                    batch_label = text_view_class(activity)
                    batch_label.setText("单批测活上限（1-3000）")
                    batch_label.setPadding(0, spacing, 0, 0)
                    batch_edit = edit_text_class(activity)
                    batch_edit.setSingleLine(True)
                    batch_edit.setInputType(
                        input_type.TYPE_CLASS_NUMBER
                        | input_type.TYPE_NUMBER_FLAG_SIGNED
                    )
                    batch_edit.setHint("留空使用默认 300")
                    batch_edit.setText(str(owner.site_test_batch_limit))

                    container.addView(path_label)
                    container.addView(path_edit)
                    container.addView(concurrency_label)
                    container.addView(concurrency_edit)
                    container.addView(batch_label)
                    container.addView(batch_edit)

                    noop_listener = NoopListener()
                    builder = builder_class(activity)
                    builder.setTitle("扫描与测活参数")
                    builder.setView(container)
                    builder.setPositiveButton("保存", noop_listener)
                    builder.setNegativeButton("取消", noop_listener)
                    dialog = builder.show()
                    save_listener = SaveButtonListener(
                        path_edit, concurrency_edit, batch_edit, dialog
                    )
                    dialog.getButton(-1).setOnClickListener(save_listener)
                    path_edit.requestFocus()
                    owner._dialog_refs.append(
                        [
                            container,
                            path_edit,
                            concurrency_edit,
                            batch_edit,
                            noop_listener,
                            save_listener,
                            dialog,
                        ]
                    )
                    owner._dialog_refs = owner._dialog_refs[-12:]

            runner = ShowDialog()
            self._dialog_refs.append(runner)
            self._dialog_refs = self._dialog_refs[-12:]
            activity.runOnUiThread(runner)
            return True, ""
        except Exception as exc:
            return False, "扫描与测活参数输入框打开失败: {}".format(exc)

    def _open_playback_proxy_dialog(self):
        try:
            from java import dynamic_proxy, jclass

            toast_class = jclass("android.widget.Toast")
            edit_text_class = jclass("android.widget.EditText")
            linear_layout_class = jclass("android.widget.LinearLayout")
            text_view_class = jclass("android.widget.TextView")
            switch_class = jclass("android.widget.Switch")
            input_type = jclass("android.text.InputType")
            click_listener = jclass(
                "android.content.DialogInterface$OnClickListener"
            )
            view_click_listener = jclass("android.view.View$OnClickListener")
            runnable_class = jclass("java.lang.Runnable")
            try:
                builder_class = jclass(
                    "com.google.android.material.dialog.MaterialAlertDialogBuilder"
                )
            except Exception:
                builder_class = jclass("android.app.AlertDialog$Builder")
            activity = self._current_android_activity(jclass)
            owner = self

            class NoopListener(dynamic_proxy(click_listener)):
                def onClick(self, dialog, which):
                    return None

            class SaveButtonListener(dynamic_proxy(view_click_listener)):
                def __init__(self, enabled_switch, urls_edit, dialog):
                    super().__init__()
                    self.enabled_switch = enabled_switch
                    self.urls_edit = urls_edit
                    self.dialog = dialog

                def onClick(self, view):
                    try:
                        raw_urls = str(self.urls_edit.getText().toString())
                        enabled = bool(self.enabled_switch.isChecked())
                        if raw_urls.strip() and not owner.playback_proxy_urls:
                            enabled = True
                        with owner.lock:
                            saved = owner._set_playback_proxy_settings(
                                enabled,
                                raw_urls,
                                verify_remote=True,
                            )
                        toast_class.makeText(
                            activity,
                            "反代线路设置已保存：{}，{} 条地址".format(
                                "开启" if saved["enabled"] else "关闭",
                                len(saved["urls"]),
                            ),
                            toast_class.LENGTH_LONG,
                        ).show()
                        self.dialog.dismiss()
                    except Exception as exc:
                        toast_class.makeText(
                            activity,
                            "反代线路设置保存失败: {}".format(exc),
                            toast_class.LENGTH_LONG,
                        ).show()

            class ShowDialog(dynamic_proxy(runnable_class)):
                def run(self):
                    density = float(
                        activity.getResources().getDisplayMetrics().density
                    )
                    padding = int(16 * density + 0.5)
                    spacing = int(8 * density + 0.5)
                    container = linear_layout_class(activity)
                    container.setOrientation(linear_layout_class.VERTICAL)
                    container.setPadding(padding, spacing, padding, 0)
                    description = text_view_class(activity)
                    description.setText(
                        "每行一个线路地址；保存时验证目标转发，支持路径前缀和带凭据线路"
                    )
                    description.setTextSize(13.0)
                    enabled_switch = switch_class(activity)
                    enabled_switch.setText("自动启用反代线路")
                    enabled_switch.setChecked(bool(owner.playback_proxy_enabled))
                    enabled_switch.setPadding(0, spacing, 0, spacing)
                    urls_edit = edit_text_class(activity)
                    urls_edit.setSingleLine(False)
                    urls_edit.setMinLines(3)
                    urls_edit.setMaxLines(8)
                    urls_edit.setInputType(
                        input_type.TYPE_CLASS_TEXT
                        | input_type.TYPE_TEXT_VARIATION_URI
                        | input_type.TYPE_TEXT_FLAG_MULTI_LINE
                    )
                    urls_edit.setText("\n".join(owner.playback_proxy_urls))
                    container.addView(description)
                    container.addView(enabled_switch)
                    container.addView(urls_edit)
                    noop_listener = NoopListener()
                    builder = builder_class(activity)
                    builder.setTitle("反代线路")
                    builder.setView(container)
                    builder.setPositiveButton("保存", noop_listener)
                    builder.setNegativeButton("取消", noop_listener)
                    dialog = builder.show()
                    save_listener = SaveButtonListener(
                        enabled_switch, urls_edit, dialog
                    )
                    dialog.getButton(-1).setOnClickListener(save_listener)
                    owner._dialog_refs.append(
                        [
                            container,
                            description,
                            enabled_switch,
                            urls_edit,
                            noop_listener,
                            save_listener,
                            dialog,
                        ]
                    )
                    owner._dialog_refs = owner._dialog_refs[-12:]

            runner = ShowDialog()
            self._dialog_refs.append(runner)
            self._dialog_refs = self._dialog_refs[-12:]
            activity.runOnUiThread(runner)
            return True, ""
        except Exception as exc:
            return False, "反代线路设置打开失败: {}".format(exc)

    def _normalize_package_download_url(self, value):
        url = str(value or "").strip().strip('"').strip("'")
        if not url:
            raise ValueError("下载地址不能为空")
        if len(url) > 2048:
            raise ValueError("下载地址过长")
        parsed = urllib.parse.urlsplit(url)
        if parsed.scheme.lower() not in ("http", "https") or not parsed.netloc:
            raise ValueError("下载地址必须是 http 或 https URL")
        return url

    def _package_download_url_identity(self, value):
        return self._encoded_download_url(value).casefold()

    def _package_download_url_looks_zip(self, value):
        try:
            path = urllib.parse.unquote(
                urllib.parse.urlsplit(
                    self._normalize_package_download_url(value)
                ).path
            )
            return path.rstrip("/").lower().endswith(".zip")
        except Exception:
            return False

    def _package_request_headers(self, accept="*/*"):
        headers = {
            "User-Agent": "okhttp/4.12.0",
            "Accept": accept,
            "X-Device-ID": self.package_device_id,
            "X-Client-Version": self.VERSION,
            "Connection": "close",
        }
        if self._package_authorization_ticket:
            headers["X-Release-Ticket"] = self._package_authorization_ticket
        return headers

    def _package_service_error(self, error):
        status = int(getattr(error, "code", 0) or 0)
        headers = getattr(error, "headers", None)
        retry_after = str(headers.get("Retry-After", "") if headers else "").strip()
        code = str(headers.get("X-Package-Code", "") if headers else "").strip()
        message = ""
        try:
            payload = error.read(8192)
            data = json.loads(payload.decode("utf-8-sig"))
            if isinstance(data, dict):
                code = str(data.get("code", code) or code).strip()
                message = str(data.get("message", data.get("error", "")) or "").strip()
                retry_after = str(data.get("retryAfter", retry_after) or retry_after).strip()
        except Exception:
            pass
        try:
            retry_seconds = max(0, int(float(retry_after)))
        except Exception:
            retry_seconds = 0
        if code == "SERVICE_DISABLED":
            text = "接口已关闭：{}".format(message or "服务维护中，请稍后再试")
            return PackageServiceRequestError(text, status, code, retry_seconds)
        if code == "RATE_LIMITED":
            seconds = max(1, retry_seconds)
            wait = "{} 秒".format(seconds) if seconds < 60 else "{} 分钟".format((seconds + 59) // 60)
            text = "请求次数已达上限：{}（{}后重试）".format(message or "访问过于频繁", wait)
            return PackageServiceRequestError(text, status, code, seconds)
        if code == "CLIENT_UPGRADE_REQUIRED":
            text = message or "接口要求使用本地影仓 v4.0 或更高版本"
            return PackageServiceRequestError(text, status, code, retry_seconds)
        text = message or "CF 接口返回 HTTP {}".format(status)
        return PackageServiceRequestError(text, status, code, retry_seconds)

    def _package_cf_url(
        self, value, include_sites=None, include_lives=None, source_url=None
    ):
        url = self._normalize_package_download_url(value)
        if (
            include_sites is None
            and include_lives is None
            and source_url is None
        ):
            return url
        parsed = urllib.parse.urlsplit(url)
        query = urllib.parse.parse_qsl(parsed.query, keep_blank_values=True)
        query = [
            (key, item)
            for key, item in query
            if key not in ("sites", "lives", "url")
        ]
        if source_url is not None and str(source_url).strip():
            query.append(
                ("url", self._normalize_package_download_url(source_url))
            )
        if include_sites is not None:
            query.append(("sites", "1" if include_sites else "0"))
        if include_lives is not None:
            query.append(("lives", "1" if include_lives else "0"))
        return urllib.parse.urlunsplit(
            (parsed.scheme, parsed.netloc, parsed.path, urllib.parse.urlencode(query), parsed.fragment)
        )

    def _package_open_url(self, value, timeout=15, accept="*/*", method="GET"):
        url = self._normalize_package_download_url(value)
        request = urllib.request.Request(
            self._encoded_download_url(url),
            headers=self._package_request_headers(accept),
            method=str(method or "GET").upper(),
        )
        opener = urllib.request.build_opener(urllib.request.ProxyHandler({}))
        try:
            return opener.open(request, timeout=max(2, int(timeout)))
        except urllib.error.HTTPError as exc:
            raise self._package_service_error(exc)

    def _package_open_direct_url(
        self, value, timeout=15, accept="*/*", method="GET", range_header=""
    ):
        url = self._normalize_package_download_url(value)
        headers = {
            "User-Agent": "okhttp/4.12.0",
            "Accept": accept,
            "Connection": "close",
        }
        if range_header:
            headers["Range"] = str(range_header)
        request = urllib.request.Request(
            self._encoded_download_url(url),
            headers=headers,
            method=str(method or "GET").upper(),
        )
        opener = urllib.request.build_opener(urllib.request.ProxyHandler({}))
        return opener.open(request, timeout=max(2, int(timeout)))

    def _package_read_limited(self, response, limit, initial=b""):
        payload = bytearray(initial or b"")
        while True:
            chunk = response.read(min(128 * 1024, int(limit) + 1 - len(payload)))
            if not chunk:
                break
            payload.extend(chunk)
            if len(payload) > int(limit):
                raise ValueError("下载内容超过大小上限")
        return bytes(payload)

    def _package_parse_json_text(self, text):
        value = str(text or "").lstrip("\ufeff")
        try:
            return json.loads(value)
        except json.JSONDecodeError:
            cleaned = self._strip_json_trailing_commas(
                self._strip_json_comments(value)
            )
            return json.loads(cleaned)

    def _package_header_int(self, headers, name):
        try:
            return max(0, int(str(headers.get(name, "0") or "0").strip()))
        except (TypeError, ValueError, OverflowError):
            return 0

    def _probe_cf_package_download_url(self, value, timeout=8):
        source_url = self._normalize_package_download_url(value)
        if not self.package_service_url:
            raise ValueError("未配置 CF 解析服务地址")
        url = self._package_cf_url(
            self.package_service_url,
            include_sites=True,
            include_lives=True,
            source_url=source_url,
        )
        try:
            with self._package_open_url(
                url,
                timeout=timeout,
                accept="application/zip, application/json, text/plain, application/octet-stream, */*",
                method="HEAD",
            ) as response:
                status = int(getattr(response, "status", response.getcode()))
                if status < 200 or status >= 300:
                    raise ValueError("网址返回 HTTP {}".format(status))
                final_url = str(getattr(response, "geturl", lambda: url)() or url)
                content_length = str(response.headers.get("Content-Length", "")).strip()
                total_size = int(content_length) if content_length.isdigit() else 0
                if total_size > self.MAX_PACKAGE_DOWNLOAD_SIZE:
                    raise ValueError("下载内容超过大小上限")
                content_type = str(response.headers.get("Content-Type", "")).split(
                    ";", 1
                )[0].strip()
                if content_type in ("application/zip", "application/octet-stream"):
                    return {
                        "url": source_url,
                        "status": status,
                        "content_type": content_type,
                        "size": total_size,
                        "zip": True,
                        "source_type": "config",
                        "site_count": self._package_header_int(
                            response.headers, "X-Package-Sites"
                        ),
                        "dependency_count": self._package_header_int(
                            response.headers, "X-Package-Dependencies"
                        ),
                        "live_count": self._package_header_int(
                            response.headers, "X-Package-Lives"
                        ),
                    }
                raise ValueError(
                    "CF 没有返回 ZIP 本地包（Content-Type: {}）；"
                    "请检查解析服务是否允许动态接口转换".format(
                        content_type or "未知"
                    )
                )
        except urllib.error.HTTPError as exc:
            raise ValueError("网址访问失败：HTTP {}".format(exc.code))
        except urllib.error.URLError as exc:
            raise ValueError("网址访问失败：{}".format(exc.reason))
        except (socket.timeout, TimeoutError):
            raise ValueError("网址检测超时")

    def _probe_direct_zip_url(self, value, timeout=8):
        url = self._normalize_package_download_url(value)
        try:
            with self._package_open_direct_url(
                url,
                timeout=timeout,
                accept="application/zip, application/octet-stream, */*",
                range_header="bytes=0-3",
            ) as response:
                status = int(getattr(response, "status", response.getcode()))
                if status < 200 or status >= 300:
                    raise ValueError("网址返回 HTTP {}".format(status))
                length = str(response.headers.get("Content-Length", "")).strip()
                total_size = int(length) if length.isdigit() else 0
                content_range = str(response.headers.get("Content-Range", ""))
                match = re.search(r"/(\d+)\s*$", content_range)
                if match:
                    total_size = int(match.group(1))
                if total_size > self.MAX_PACKAGE_DOWNLOAD_SIZE:
                    raise ValueError("下载内容超过大小上限")
                signature = response.read(4)
                if signature not in (b"PK\x03\x04", b"PK\x05\x06", b"PK\x07\x08"):
                    raise ValueError("网址不是 ZIP 本地包")
                content_type = str(response.headers.get("Content-Type", "")).split(
                    ";", 1
                )[0].strip()
                return {
                    "url": str(
                        getattr(response, "geturl", lambda: url)() or url
                    ),
                    "status": status,
                    "content_type": content_type,
                    "size": total_size,
                    "zip": True,
                    "source_type": "zip",
                    "site_count": 0,
                    "dependency_count": 0,
                    "live_count": 0,
                }
        except urllib.error.HTTPError as exc:
            raise ValueError("ZIP 网址访问失败：HTTP {}".format(exc.code))
        except urllib.error.URLError as exc:
            raise ValueError("ZIP 网址访问失败：{}".format(exc.reason))
        except (socket.timeout, TimeoutError):
            raise ValueError("ZIP 网址检测超时")

    def _probe_package_download_url(self, value, timeout=8):
        try:
            return self._probe_cf_package_download_url(value, timeout=timeout)
        except ValueError as cf_error:
            try:
                return self._probe_direct_zip_url(value, timeout=timeout)
            except ValueError:
                raise cf_error

    def _enabled_package_download_sites(self):
        return [
            dict(item)
            for item in self.package_download_sites
            if self._package_download_site_active(item)
        ]

    def _find_package_download_site(self, site_id):
        value = str(site_id or "").strip()
        for item in self.package_download_sites:
            if str(item.get("id", "")) == value:
                return item
        return None

    def _package_download_site_type_label(self, item):
        sites = max(0, int(item.get("site_count", 0) or 0))
        dependencies = max(0, int(item.get("dependency_count", 0) or 0))
        lives = max(0, int(item.get("live_count", 0) or 0))
        source_type = str(item.get("source_type", "config")).lower()
        prefix = (
            "内置"
            if source_type == "builtin"
            else "ZIP"
            if source_type == "zip"
            else "接口"
        )
        return "{}{}/{}·直播{}".format(prefix, sites, dependencies, lives)

    def _package_download_sites_summary(self):
        return ", ".join(
            "{}[{}]:站{}·播{}·测{}".format(
                item.get("name", "未命名"),
                self._package_download_site_type_label(item),
                "开" if self._package_download_site_enabled(item) else "关",
                "开" if self._package_download_live_enabled(item) else "关",
                "开" if self._package_download_health_enabled(item) else "关",
            )
            for item in self.package_download_sites
        ) or "无"

    def _add_or_update_package_download_site(
        self, name, url, verify=False, probe=None
    ):
        if self._package_download_running():
            raise ValueError("本地包下载安装中，请完成后再更新网址")
        clean_name = self._normalize_package_download_name(name)
        clean_url = self._normalize_package_download_url(url)
        if (
            not self.package_external_configured
            and str(
                (probe if isinstance(probe, dict) else {}).get(
                    "source_type", ""
                )
            ).lower() != "zip"
        ):
            probe = self._probe_direct_zip_url(clean_url)
        elif verify:
            probe = self._probe_package_download_url(clean_url)
        probe = probe if isinstance(probe, dict) else {}
        source_type = (
            "zip"
            if str(probe.get("source_type", "")).lower() == "zip"
            or self._package_download_url_looks_zip(clean_url)
            else "config"
        )
        previous = copy.deepcopy(self.package_download_sites)
        name_match = None
        url_match = None
        for item in self.package_download_sites:
            if str(item.get("name", "")).casefold() == clean_name.casefold():
                name_match = item
            if self._package_download_url_identity(
                item.get("url", "")
            ) == self._package_download_url_identity(clean_url):
                url_match = item
        if name_match is not None and url_match is not None and name_match is not url_match:
            raise ValueError("备注名和网址分别属于两个已有站点")
        target = name_match or url_match
        created = target is None
        moved = None
        if created:
            if len(self.package_download_sites) >= 50:
                raise ValueError("下载站点最多保存 50 个")
            installed_marker = self._read_package_install_marker(
                self._package_install_target(site_name=clean_name)
            )
            installed_id = re.sub(
                r"[^A-Za-z0-9_-]+",
                "",
                str(installed_marker.get("id", "")).strip(),
            )[:40]
            target = {
                "id": installed_id
                or self._package_download_site_id(clean_name, clean_url),
                "name": clean_name,
                "url": clean_url,
                "enabled": True,
                "site_enabled": True,
                "live_enabled": True,
                "health_enabled": True,
                "source_type": source_type,
                "site_count": max(0, int(probe.get("site_count", 0) or 0)),
                "dependency_count": max(
                    0, int(probe.get("dependency_count", 0) or 0)
                ),
                "live_count": max(0, int(probe.get("live_count", 0) or 0)),
            }
            self.package_download_sites.append(target)
        else:
            old_name = str(target.get("name", "")).strip()
            if old_name and old_name != clean_name:
                moved = self._rename_package_install_directory(
                    target.get("id", ""), old_name, clean_name
                )
            target["name"] = clean_name
            target["url"] = clean_url
            target["source_type"] = source_type
            target["site_count"] = max(
                0, int(probe.get("site_count", 0) or 0)
            )
            target["dependency_count"] = max(
                0, int(probe.get("dependency_count", 0) or 0)
            )
            target["live_count"] = max(
                0, int(probe.get("live_count", 0) or 0)
            )
        try:
            self._sync_legacy_package_download_fields()
            self._save_settings()
        except Exception:
            self.package_download_sites = previous
            self._sync_legacy_package_download_fields()
            try:
                self._rollback_package_install_rename(moved)
            except Exception as rollback_exc:
                self._log(
                    "ERROR",
                    "下载站点备注目录回滚失败: {}".format(rollback_exc),
                )
            raise
        return dict(target), created

    def _set_package_download_site_states(self, values):
        if not isinstance(values, dict):
            raise ValueError("下载站点开关数据无效")
        previous = copy.deepcopy(self.package_download_sites)
        changed = False
        for item in self.package_download_sites:
            site_id = str(item.get("id", ""))
            if site_id not in values:
                continue
            state = values[site_id]
            if isinstance(state, dict):
                site_enabled = bool(state.get("site", state.get("site_enabled", True)))
                live_enabled = bool(state.get("live", state.get("live_enabled", True)))
                health_enabled = bool(
                    state.get("health", state.get("health_enabled", True))
                )
            else:
                site_enabled = bool(state)
                live_enabled = bool(state)
                health_enabled = True
            if (
                self._package_download_site_enabled(item) != site_enabled
                or self._package_download_live_enabled(item) != live_enabled
                or self._package_download_health_enabled(item) != health_enabled
            ):
                item["site_enabled"] = site_enabled
                item["live_enabled"] = live_enabled
                item["health_enabled"] = health_enabled
                item["enabled"] = bool(site_enabled or live_enabled)
                changed = True
        try:
            self._sync_legacy_package_download_fields()
            self._save_settings()
        except Exception:
            self.package_download_sites = previous
            self._sync_legacy_package_download_fields()
            raise
        return changed

    def _delete_package_download_sites(self, site_ids):
        if self._package_download_running():
            raise ValueError("本地包下载安装中，请完成后再删除")
        selected = {
            str(item).strip() for item in site_ids if str(item).strip()
        } if isinstance(site_ids, (list, tuple, set)) else set()
        if not selected:
            raise ValueError("请选择要删除的下载站点")
        existing_ids = {
            str(item.get("id", "")).strip()
            for item in self.package_download_sites
        }
        matched = selected & existing_ids
        if not matched:
            raise ValueError("选择的下载站点已不存在")
        previous = copy.deepcopy(self.package_download_sites)
        removed = [
            dict(item)
            for item in self.package_download_sites
            if str(item.get("id", "")).strip() in matched
        ]
        deletion = self._stage_package_install_deletions(removed)
        self.package_download_sites = [
            item
            for item in self.package_download_sites
            if str(item.get("id", "")).strip() not in matched
        ]
        try:
            self._sync_legacy_package_download_fields()
            self._save_settings()
        except Exception:
            self.package_download_sites = previous
            self._sync_legacy_package_download_fields()
            try:
                self._rollback_package_install_deletions(deletion)
            except Exception as rollback_exc:
                self._log(
                    "ERROR",
                    "下载站点删除回滚失败: {}".format(rollback_exc),
                )
            raise
        removed_counts = {}
        for entry in deletion.get("entries", []):
            site_id = str(entry.get("site_id", "")).strip()
            removed_counts[site_id] = removed_counts.get(site_id, 0) + 1
        for item in removed:
            item["removed_package_dirs"] = removed_counts.get(
                str(item.get("id", "")).strip(), 0
            )
        quarantine = str(deletion.get("quarantine", "")).strip()
        cleanup_error = ""
        if quarantine:
            try:
                shutil.rmtree(quarantine)
            except Exception as exc:
                cleanup_error = str(exc)
                self._log(
                    "WARN",
                    "本地包已移出扫描目录，但临时回收目录清理失败: {} ({})".format(
                        quarantine, exc
                    ),
                )
        for item in removed:
            item["package_cleanup_error"] = cleanup_error
        return removed

    def _open_package_download_url_dialog(self):
        try:
            from java import dynamic_proxy, jclass

            toast_class = jclass("android.widget.Toast")
            edit_text_class = jclass("android.widget.EditText")
            linear_layout_class = jclass("android.widget.LinearLayout")
            text_view_class = jclass("android.widget.TextView")
            input_type = jclass("android.text.InputType")
            click_listener = jclass(
                "android.content.DialogInterface$OnClickListener"
            )
            runnable_class = jclass("java.lang.Runnable")
            try:
                builder_class = jclass(
                    "com.google.android.material.dialog.MaterialAlertDialogBuilder"
                )
            except Exception:
                builder_class = jclass("android.app.AlertDialog$Builder")
            activity = self._current_android_activity(jclass)
            owner = self

            class SaveListener(dynamic_proxy(click_listener)):
                def __init__(self, name_edit, url_edit):
                    super().__init__()
                    self.name_edit = name_edit
                    self.url_edit = url_edit

                def onClick(self, dialog, which):
                    try:
                        name = str(self.name_edit.getText().toString())
                        url = str(self.url_edit.getText().toString())
                        clean_name = owner._normalize_package_download_name(name)
                        clean_url = owner._normalize_package_download_url(url)
                        def save_site():
                            try:
                                probe = None
                                if not owner.package_external_configured:
                                    probe = owner._probe_direct_zip_url(clean_url)
                                with owner.lock:
                                    saved, created = owner._add_or_update_package_download_site(
                                        clean_name,
                                        clean_url,
                                        verify=False,
                                        probe=probe,
                                    )
                                owner._notify_app(
                                    "已{}{}：{}；请在推荐页点击“下载本地包”".format(
                                        "添加" if created else "更新",
                                        "接口"
                                        if owner.package_external_configured
                                        else " ZIP 直链",
                                        saved["name"],
                                    )
                                )
                            except Exception as exc:
                                owner._notify_app(
                                    "接口保存失败：{}".format(exc)
                                )

                        toast_class.makeText(
                            activity,
                            "保存接口中"
                            if owner.package_external_configured
                            else "校验 ZIP 直链中",
                            toast_class.LENGTH_SHORT,
                        ).show()
                        if owner.package_external_configured:
                            save_site()
                        else:
                            worker = threading.Thread(
                                target=save_site,
                                name="local-package-zip-check",
                            )
                            worker.daemon = True
                            worker.start()
                    except Exception as exc:
                        toast_class.makeText(
                            activity,
                            "下载地址保存失败: {}".format(exc),
                            toast_class.LENGTH_LONG,
                        ).show()

            class CancelListener(dynamic_proxy(click_listener)):
                def onClick(self, dialog, which):
                    return None

            class ShowDialog(dynamic_proxy(runnable_class)):
                def run(self):
                    density = float(
                        activity.getResources().getDisplayMetrics().density
                    )
                    padding = int(16 * density + 0.5)
                    row_padding = int(8 * density + 0.5)
                    container = linear_layout_class(activity)
                    container.setOrientation(linear_layout_class.VERTICAL)
                    container.setPadding(padding, row_padding, padding, 0)
                    description = text_view_class(activity)
                    description.setText(
                        "未配置解析服务，仅支持 ZIP 本地包直链，保存时校验格式"
                        if not owner.package_external_configured
                        else "已配置解析服务，支持 JSON 接口或 ZIP 直链"
                    )
                    description.setTextSize(13.0)
                    description.setPadding(0, 0, 0, row_padding)
                    container.addView(description)
                    name_edit = edit_text_class(activity)
                    name_edit.setSingleLine(True)
                    name_edit.setHint("备注名，例如：第二线路")
                    name_edit.setInputType(input_type.TYPE_CLASS_TEXT)
                    container.addView(name_edit)
                    url_edit = edit_text_class(activity)
                    url_edit.setSingleLine(True)
                    url_edit.setInputType(
                        input_type.TYPE_CLASS_TEXT
                        | input_type.TYPE_TEXT_VARIATION_URI
                    )
                    url_edit.setHint(
                        "http://摸鱼儿.cc 或 https://example.com/package.zip"
                        if owner.package_external_configured
                        else "https://example.com/package.zip"
                    )
                    container.addView(url_edit)
                    save_listener = SaveListener(name_edit, url_edit)
                    cancel_listener = CancelListener()
                    builder = builder_class(activity)
                    builder.setTitle("添加本地包接口")
                    builder.setView(container)
                    builder.setPositiveButton("保存", save_listener)
                    builder.setNegativeButton("取消", cancel_listener)
                    dialog = builder.show()
                    name_edit.requestFocus()
                    owner._dialog_refs.extend(
                        [
                            container,
                            description,
                            name_edit,
                            url_edit,
                            save_listener,
                            cancel_listener,
                            dialog,
                        ]
                    )
                    owner._dialog_refs = owner._dialog_refs[-12:]

            runner = ShowDialog()
            self._dialog_refs.append(runner)
            self._dialog_refs = self._dialog_refs[-12:]
            activity.runOnUiThread(runner)
            return True, ""
        except Exception as exc:
            return False, "下载地址输入框打开失败: {}".format(exc)

