            click_listener = jclass(
                "android.content.DialogInterface$OnClickListener"
            )
            runnable_class = jclass("java.lang.Runnable")
            try:
                builder_class = jclass(
                    "com.google.android.material.dialog.MaterialAlertDialogBuilder"
                )
            except Exception:
                builder_class = jclass("android.app.AlertDialog$Builder")
            activity = self._current_android_activity(jclass)
            owner = self
            choices = [
                ("自动判断（无可靠证据时保持直连）", "auto", ""),
                ("强制直连", "force_direct", ""),
            ]
            choices.extend(
                (
                    "强制反代 · {}".format(
                        self._playback_proxy_line_label(prefix)
                    ),
                    "force_proxy",
                    prefix,
                )
                for prefix in self.playback_proxy_urls
                if self._live_proxy_capability_available(prefix)
            )
            state = self._live_proxy_policy(live_entry)
            current_policy = str(state.get("policy", "auto") or "auto")
            current_prefix = str(state.get("prefix", "") or "")
            selected = 0
            for index, (_label, policy, prefix) in enumerate(choices):
                if policy == current_policy and (
                    policy != "force_proxy" or prefix == current_prefix
                ):
                    selected = index
                    break
            selection = {"index": selected}

            class ChoiceListener(dynamic_proxy(click_listener)):
                def onClick(self, dialog, which):
                    selection["index"] = int(which)

            class ApplyListener(dynamic_proxy(click_listener)):
                def onClick(self, dialog, which):
                    index = max(
                        0, min(selection["index"], len(choices) - 1)
                    )
                    _label, policy, prefix = choices[index]
                    started, message = owner._start_live_proxy_policy_update(
                        live_entry, policy, prefix
                    )
                    owner._notify_app(message)
                    if not started:
                        owner._log("WARN", message)

