    def _open_batch_live_proxy_dialog(self, policy):
        try:
            from java import dynamic_proxy, jclass

            multi_listener = jclass(
                "android.content.DialogInterface$OnMultiChoiceClickListener"
            )
            click_listener = jclass(
                "android.content.DialogInterface$OnClickListener"
            )
            runnable_class = jclass("java.lang.Runnable")
            try:
                builder_class = jclass(
                    "com.google.android.material.dialog.MaterialAlertDialogBuilder"
                )
            except Exception:
                builder_class = jclass("android.app.AlertDialog$Builder")
            activity = self._current_android_activity(jclass)
            owner = self
            prefix = ""
            if policy == "force_proxy":
                prefix = next(
                    (
                        value for value in self.playback_proxy_urls
                        if self._live_proxy_capability_available(value)
                    ),
                    "",
                )
                if not prefix:
                    return False, "当前线路不支持 HTTP(S) 媒体转发"
            candidates = []
            for item in self.cache.get("lives", []):
                if not self._live_proxy_supported(item.get("live", {})):
                    continue
                current = self._live_proxy_policy(item)
                current_policy = str(current.get("policy", "auto") or "auto")
                if policy == "auto" and current_policy == "auto":
                    continue
                if policy == "force_direct" and current_policy == policy:
                    continue
                if (
                    policy == "force_proxy"
                    and current_policy == policy
                    and str(current.get("prefix", "") or "") == prefix
                ):
                    continue
                candidates.append(item)
            if not candidates:
                return False, "当前没有需要批量更新的直播源"
            labels = [
                "{} · {}".format(
                    item.get("live", {}).get("name", "未命名直播"),
                    self._live_proxy_policy_label(item),
                )
                for item in candidates
            ]
            selected = [False] * len(candidates)

            class SelectListener(dynamic_proxy(multi_listener)):
                def onClick(self, dialog, which, checked):
                    index = int(which)
                    if 0 <= index < len(selected):
                        selected[index] = bool(checked)

            class ApplyListener(dynamic_proxy(click_listener)):
                def onClick(self, dialog, which):
                    chosen = [
                        item for index, item in enumerate(candidates)
                        if selected[index]
                    ]
                    if not chosen:
                        owner._notify_app("请至少选择一个直播源")
                        return
                    started, message = owner._start_batch_live_proxy_update(
                        chosen, policy, prefix
                    )
                    owner._notify_app(message)
                    if not started:
                        owner._log("WARN", message)

            class ShowDialog(dynamic_proxy(runnable_class)):
                def run(self):
                    try:
                        select_listener = SelectListener()
                        apply_listener = ApplyListener()
                        builder = builder_class(activity)
                        title = {
                            "auto": "批量恢复直播自动判断",
                            "force_direct": "批量强制直播直连",
                            "force_proxy": "批量强制直播反代",
                        }[policy]
                        builder.setTitle(title)
                        builder.setMultiChoiceItems(
                            labels, selected, select_listener
                        )
                        builder.setPositiveButton("保存并重载", apply_listener)
                        builder.setNegativeButton("取消", None)
                        dialog = builder.show()
                        owner._dialog_refs.append(
                            [
                                dialog,
                                candidates,
                                labels,
                                selected,
                                select_listener,
                                apply_listener,
                            ]
                        )
                        owner._dialog_refs = owner._dialog_refs[-12:]
                    except Exception as exc:
                        message = "批量直播反代界面打开失败: {}".format(exc)
                        owner._log("ERROR", message)
                        owner._notify_app(message)

            runner = ShowDialog()
            self._dialog_refs.append(runner)
            self._dialog_refs = self._dialog_refs[-12:]
            activity.runOnUiThread(runner)
            return True, ""
        except Exception as exc:
            return False, "批量直播反代界面打开失败: {}".format(exc)

